export interface ConnectorConfig {
  /** Airtable API key (Bearer token) */
  airtableApiKey: string
  /** Airtable base ID (e.g., 'appXXXXXXXXXXXXXX') */
  airtableBaseId: string
  /** Airtable table ID or name (e.g., 'tblXXXXXXXXXXXXXX' or 'Orders') */
  airtableTableId: string
  /** Shopify webhook shared secret for HMAC verification */
  shopifyWebhookSecret: string
  /** Optional injected fetch for testing */
  fetch?: typeof fetch
}

export interface ShopifyOrderPaidPayload {
  ucp: {
    version: string
    capabilities: {
      'dev.ucp.shopping.order': Array<{ version: string }>
    }
  }
  id: string
  label: string
  currency: string
  totals: Array<{
    type: string
    display_text: string
    amount: number
  }>
  line_items: unknown[]
  fulfillment: Record<string, unknown>
  /** Customer email may be present in extended UCP structure */
  email?: string
  /** Additional fields that may contain customer info */
  customer?: {
    email?: string
  }
  billing_address?: {
    email?: string
  }
}

export interface HandleResult {
  createdRecordIds: string[]
  airtableResponse: {
    records: Array<{
      id: string
      createdTime: string
      fields: Record<string, unknown>
    }>
  }
}

function extractOrderId(shopifyId: string): string {
  const match = shopifyId.match(/\/Order\/(\d+)$/)
  return match ? match[1] : shopifyId
}

function extractTotal(totals: Array<{ type: string; amount: number }>): number {
  const total = totals.find((t) => t.type === 'total')
  if (!total) throw new Error('Missing total amount in payload')
  return total.amount / 100
}

function extractEmail(payload: ShopifyOrderPaidPayload): string {
  if (payload.email) return payload.email
  if (payload.customer?.email) return payload.customer.email
  if (payload.billing_address?.email) return payload.billing_address.email
  throw new Error('Customer email not found in payload')
}

async function verifyShopifyHmac(
  payload: string,
  hmacHeader: string | null,
  secret: string,
): Promise<void> {
  if (!hmacHeader) throw new Error('Missing X-Shopify-Hmac-SHA256 header')
  const encoder = new TextEncoder()
  const key = await crypto.subtle.importKey('raw', encoder.encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign'])
  const signature = await crypto.subtle.sign('HMAC', key, encoder.encode(payload))
  const expected = Buffer.from(signature).toString('base64')
  if (hmacHeader !== expected) throw new Error('Invalid Shopify HMAC signature')
}

export async function handle(
  payload: ShopifyOrderPaidPayload,
  config: ConnectorConfig,
): Promise<HandleResult> {
  const fetch = config.fetch ?? globalThis.fetch
  if (!fetch) throw new Error('fetch is not available')

  if (!payload.id) throw new Error('Missing required field: id')
  if (!payload.totals || !Array.isArray(payload.totals)) throw new Error('Missing required field: totals')

  const orderId = extractOrderId(payload.id)
  const total = extractTotal(payload.totals)
  const email = extractEmail(payload)

  const url = `https://api.airtable.com/v0/${config.airtableBaseId}/${config.airtableTableId}`
  const body = {
    records: [
      {
        fields: {
          'Order ID': orderId,
          'Customer Email': email,
          Total: total,
        },
      },
    ],
  }

  const response = await fetch(url, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.airtableApiKey}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(body),
  })

  if (!response.ok) {
    const text = await response.text()
    throw new Error(`Airtable API error: ${response.status} ${response.statusText} at ${url} - ${text}`)
  }

  const data = (await response.json()) as HandleResult['airtableResponse']
  const createdRecordIds = data.records.map((r) => r.id)

  return { createdRecordIds, airtableResponse: data }
}

